-- Private helper: invoker, no user EXECUTE. Does not trust historical team/job participants.
create function mir_core.chat_member_allowed(org uuid,conversation uuid,member uuid) returns boolean
language sql stable set search_path=pg_catalog,mir_core as $fn$
 select coalesce(exists(select 1 from mir_core.memberships m join mir_core.conversations c on c.organization_id=m.organization_id
 where m.organization_id=org and m.user_id=member and m.active and m.role in('admin','employee') and c.id=conversation and case c.kind
 when 'private' then exists(select 1 from mir_core.conversation_participants p where p.organization_id=org and p.conversation_id=c.id and p.user_id=member and p.active)
 when 'team' then exists(select 1 from mir_core.teams t join mir_core.team_members tm on(tm.organization_id,tm.team_id)=(t.organization_id,t.id)
  where t.organization_id=org and t.id=c.team_id and t.active and tm.user_id=member and tm.active)
 when 'job' then exists(select 1 from mir_core.jobs j where j.organization_id=org and j.id=c.job_id) and
  case when member=auth.uid() then mir_core.job_dossier_allowed(org,c.job_id,member)
  else mir_core.staff_role(org,member) in('admin','boss','assistant')
   or exists(select 1 from mir_core.job_memberships jm where jm.organization_id=org and jm.job_id=c.job_id and jm.user_id=member)
   or (mir_core.staff_role(org,member)='warehouse' and exists(select 1 from mir_core.delivery_run_orders d where d.organization_id=org and d.job_id=c.job_id)) end
 else false end),false);
$fn$;
create or replace function mir_core.conversation_allowed(org uuid,conversation uuid,member uuid default auth.uid()) returns boolean
language sql stable security definer set search_path=pg_catalog,mir_core as $fn$
 select coalesce(auth.uid() is not null and member=auth.uid() and mir_core.chat_member_allowed(org,conversation,member),false);
$fn$;
create or replace function public.mir_conversation_team(org uuid,team uuid) returns uuid
language plpgsql security definer set search_path=pg_catalog,mir_core as $fn$
declare result uuid;
begin
 if auth.uid() is null or not exists(select 1 from mir_core.memberships m join mir_core.team_members tm on(tm.organization_id,tm.user_id)=(m.organization_id,m.user_id)
  join mir_core.teams t on(t.organization_id,t.id)=(tm.organization_id,tm.team_id)
  where m.organization_id=org and m.user_id=auth.uid() and m.active and m.role in('admin','employee') and tm.team_id=team and tm.active and t.active) then
  raise exception 'Équipe non autorisée' using errcode='42501';end if;
 insert into mir_core.conversations(organization_id,kind,team_id,created_by) values(org,'team',team,auth.uid())
 on conflict(organization_id,team_id) where kind='team' do nothing;
 select c.id into result from mir_core.conversations c where c.organization_id=org and c.kind='team' and c.team_id=team;
 return result;
end$fn$;
create function public.mir_conversation_job(org uuid,job uuid) returns uuid
language plpgsql security definer set search_path=pg_catalog,mir_core as $fn$
declare result uuid;
begin
 if auth.uid() is null or not exists(select 1 from mir_core.memberships m where m.organization_id=org and m.user_id=auth.uid() and m.active and m.role in('admin','employee'))
  or not exists(select 1 from mir_core.jobs j where j.organization_id=org and j.id=job) or not coalesce(mir_core.job_dossier_allowed(org,job),false) then
  raise exception 'Chantier non autorisé' using errcode='42501';end if;
 select c.id into result from mir_core.conversations c where c.organization_id=org and c.kind='job' and c.job_id=job;
 if result is not null then return result;end if;
 if exists(select 1 from mir_core.jobs j where j.organization_id=org and j.id=job and j.archived) then raise exception 'Chantier archivé en lecture seule' using errcode='42501';end if;
 insert into mir_core.conversations(organization_id,kind,job_id,created_by) values(org,'job',job,auth.uid())
 on conflict(organization_id,job_id) where kind='job' do nothing;
 select c.id into result from mir_core.conversations c where c.organization_id=org and c.kind='job' and c.job_id=job;
 return result;
end$fn$;
create or replace function public.mir_conversation_open(org uuid,kind text,target uuid) returns uuid
language plpgsql security definer set search_path=pg_catalog,mir_core as $fn$
begin
 if auth.uid() is null or not exists(select 1 from mir_core.memberships m where m.organization_id=org and m.user_id=auth.uid() and m.active and m.role in('admin','employee')) then raise exception 'Accès interne requis' using errcode='42501';end if;
 if kind='private' then return public.mir_conversation_private(org,target);end if;
 if kind='team' then return public.mir_conversation_team(org,target);end if;
 if kind='job' then return public.mir_conversation_job(org,target);end if;
 raise exception 'Conversation invalide' using errcode='22023';
end$fn$;
-- Storage-generated metadata only; never user_metadata. Extension and size must agree.
create function mir_core.chat_storage_object(path text,object_owner uuid,owner_id text,metadata jsonb) returns boolean
language plpgsql immutable set search_path=pg_catalog as $fn$
declare parts text[]:=string_to_array(path,'/');mime text:=metadata->>'mimetype';ext text;
begin
 if cardinality(parts)<>5 or parts[2]<>'message' or parts[1]!~'^[0-9a-f-]{36}$' or parts[3]!~'^[0-9a-f-]{36}$'
  or parts[4]!~'^[0-9a-f-]{36}$' or parts[5]!~'^[0-9a-f-]{36}\.(jpg|png|webp|heic|heif)$' then return false;end if;
 perform parts[1]::uuid,parts[3]::uuid,parts[4]::uuid,split_part(parts[5],'.',1)::uuid;
 if coalesce(owner_id,object_owner::text,'')<>parts[4] or(object_owner is not null and object_owner::text<>parts[4]) then return false;end if;
 ext:=case mime when 'image/jpeg' then 'jpg' when 'image/png' then 'png' when 'image/webp' then 'webp' when 'image/heic' then 'heic' when 'image/heif' then 'heif' end;
 if ext is null or right(parts[5],length(ext)+1)<>'.'||ext or coalesce(metadata->>'size','')!~'^[0-9]{1,8}$' then return false;end if;
 return (metadata->>'size')::bigint between 1 and 10485760;
exception when invalid_text_representation or numeric_value_out_of_range then return false;
end$fn$;
create function public.mir_message_attachment_validate(org uuid,conversation uuid,object_path text) returns jsonb
language plpgsql stable security definer set search_path=pg_catalog,mir_core,storage as $fn$
declare obj storage.objects;
begin
 if auth.uid() is null or not mir_core.conversation_allowed(org,conversation) then raise exception 'Conversation non autorisée' using errcode='42501';end if;
 if object_path is null or length(object_path)>600 or split_part(object_path,'/',1)<>org::text or split_part(object_path,'/',3)<>conversation::text
  or split_part(object_path,'/',4)<>auth.uid()::text then raise exception 'Pièce jointe non autorisée' using errcode='42501';end if;
 select o.* into obj from storage.objects o join storage.buckets b on b.id=o.bucket_id where o.bucket_id='mir-internal' and o.name=object_path and not b.public;
 if not found or not mir_core.chat_storage_object(obj.name,obj.owner,obj.owner_id,obj.metadata) then raise exception 'Pièce jointe inexistante ou invalide' using errcode='22023';end if;
 return jsonb_build_object('path',obj.name,'mime',obj.metadata->>'mimetype','size',(obj.metadata->>'size')::bigint);
end$fn$;
create or replace function public.mir_message_send(org uuid,conversation uuid,body text,job uuid,plan uuid,attachment text,request_id uuid) returns jsonb
language plpgsql security definer set search_path=pg_catalog,mir_core as $fn$
declare result uuid;recipient uuid;c mir_core.conversations;previous mir_core.messages;
begin
 if auth.uid() is null or not mir_core.conversation_allowed(org,conversation) then raise exception 'Conversation non autorisée' using errcode='42501';end if;
 select * into c from mir_core.conversations where organization_id=org and id=conversation;
 if request_id is null or body is null or length(btrim(body)) not between 1 and 4000 then raise exception 'Message invalide' using errcode='22023';end if;
 if c.kind='job' then
  if job is not null and job<>c.job_id then raise exception 'Chantier invalide' using errcode='22023';end if;job:=c.job_id;
 end if;
 if job is not null and (not exists(select 1 from mir_core.jobs j where j.organization_id=org and j.id=job) or not coalesce(mir_core.job_dossier_allowed(org,job),false)) then raise exception 'Chantier non autorisé' using errcode='42501';end if;
 -- Documents are order documents, not necessarily job plans: preserve only those readable by this actor.
 if plan is not null and not exists(select 1 from mir_core.documents d join mir_core.orders o on(o.organization_id,o.id)=(d.organization_id,d.order_id)
  where d.organization_id=org and d.id=plan and (o.owner_id=auth.uid() or mir_core.has_role(org,array['admin']))) then raise exception 'Document non autorisé' using errcode='42501';end if;
 attachment:=nullif(btrim(attachment),'');
 if attachment is not null then perform public.mir_message_attachment_validate(org,conversation,attachment);end if;
 perform pg_advisory_xact_lock(hashtextextended(org::text||auth.uid()::text||request_id::text,0));
 select * into previous from mir_core.messages where organization_id=org and sender_id=auth.uid() and client_request_id=request_id;
 if found then
  if previous.conversation_id<>conversation or previous.body<>btrim(body) or previous.job_id is distinct from job or previous.plan_document_id is distinct from plan or previous.attachment_path is distinct from attachment then raise exception 'Requête déjà utilisée avec un autre message' using errcode='22023';end if;
  return jsonb_build_object('id',previous.id,'state','sent','sentAt',previous.sent_at);
 end if;
 if job is not null and exists(select 1 from mir_core.jobs j where j.organization_id=org and j.id=job and j.archived) then raise exception 'Chantier archivé en lecture seule' using errcode='42501';end if;
 insert into mir_core.messages(organization_id,conversation_id,sender_id,client_request_id,body,job_id,plan_document_id,attachment_path)
 values(org,conversation,auth.uid(),request_id,btrim(body),job,plan,attachment) returning id into result;
 for recipient in select m.user_id from mir_core.memberships m where m.organization_id=org and m.active and m.user_id<>auth.uid() and mir_core.chat_member_allowed(org,conversation,m.user_id) loop
  insert into mir_core.message_receipts(organization_id,message_id,user_id) values(org,result,recipient);
  insert into mir_core.notifications(organization_id,user_id,kind,title,route,entity_id) values(org,recipient,'message','Nouveau message',jsonb_build_object('view','messages','conversationId',conversation),result);
 end loop;
 return jsonb_build_object('id',result,'state','sent','sentAt',(select sent_at from mir_core.messages where organization_id=org and id=result));
end$fn$;
create or replace function public.mir_message_ack(org uuid,message uuid,state text) returns jsonb
language plpgsql security definer set search_path=pg_catalog,mir_core as $fn$
declare receipt mir_core.message_receipts;conversation uuid;
begin
 if auth.uid() is null or state is null or state not in('delivered','read') then raise exception 'Accusé invalide' using errcode='22023';end if;
 select m.conversation_id into conversation from mir_core.messages m where m.organization_id=org and m.id=message;
 if not mir_core.conversation_allowed(org,conversation) then raise exception 'Conversation non autorisée' using errcode='42501';end if;
 update mir_core.message_receipts set delivered_at=coalesce(delivered_at,now()),read_at=case when state='read' then coalesce(read_at,now()) else read_at end
 where organization_id=org and message_id=message and user_id=auth.uid() returning * into receipt;
 if not found then raise exception 'Message non autorisé' using errcode='42501';end if;
 if state='read' then update mir_core.notifications set read_at=coalesce(read_at,now()) where organization_id=org and user_id=auth.uid() and kind='message' and entity_id=message;end if;
 return jsonb_build_object('deliveredAt',receipt.delivered_at,'readAt',receipt.read_at);
end$fn$;
-- Internal projections never expose client_request_id or other tenants.
create function mir_core.chat_message_json(org uuid,message uuid) returns jsonb
language sql stable set search_path=pg_catalog,mir_core as $fn$
 select jsonb_build_object('id',m.id,'conversationId',m.conversation_id,'senderId',m.sender_id,'body',m.body,'jobId',m.job_id,'planDocumentId',m.plan_document_id,'attachmentPath',m.attachment_path,'sentAt',m.sent_at,
  'deliveredCount',(select count(*) from mir_core.message_receipts r where r.organization_id=org and r.message_id=m.id and r.delivered_at is not null),
  'readCount',(select count(*) from mir_core.message_receipts r where r.organization_id=org and r.message_id=m.id and r.read_at is not null),
  'recipientCount',(select count(*) from mir_core.message_receipts r where r.organization_id=org and r.message_id=m.id),
  'myReadAt',(select r.read_at from mir_core.message_receipts r where r.organization_id=org and r.message_id=m.id and r.user_id=auth.uid()),
  'myReceipt',exists(select 1 from mir_core.message_receipts r where r.organization_id=org and r.message_id=m.id and r.user_id=auth.uid()))
 from mir_core.messages m where m.organization_id=org and m.id=message;
$fn$;
create function public.mir_chat_messages(org uuid,conversation uuid,page_size integer default 20,page_before jsonb default null) returns jsonb
language plpgsql stable security definer set search_path=pg_catalog,mir_core as $fn$
declare size integer:=least(greatest(coalesce(page_size,20),1),50);items jsonb;last_item jsonb;more boolean;stamp timestamptz;cursor_id uuid;
begin
 if auth.uid() is null or not mir_core.conversation_allowed(org,conversation) then raise exception 'Conversation non autorisée' using errcode='42501';end if;
 if page_before is not null then
  begin stamp:=(page_before->>'sentAt')::timestamptz;cursor_id:=(page_before->>'id')::uuid;exception when others then raise exception 'Curseur invalide' using errcode='22023';end;
  if not exists(select 1 from mir_core.messages m where m.organization_id=org and m.conversation_id=conversation and m.id=cursor_id and m.sent_at=stamp) then raise exception 'Curseur non autorisé' using errcode='22023';end if;
 end if;
 select coalesce(jsonb_agg(mir_core.chat_message_json(org,x.id) order by x.sent_at desc,x.id desc),'[]') into items from
  (select m.id,m.sent_at from mir_core.messages m where m.organization_id=org and m.conversation_id=conversation and(stamp is null or(m.sent_at,m.id)<(stamp,cursor_id)) order by m.sent_at desc,m.id desc limit size+1) x;
 more:=jsonb_array_length(items)>size;if more then items:=items-size;end if;last_item:=items->(jsonb_array_length(items)-1);
 return jsonb_build_object('items',items,'hasMore',more,'nextCursor',case when more then jsonb_build_object('sentAt',last_item->>'sentAt','id',last_item->>'id') end,
  'conversation',(select jsonb_build_object('id',c.id,'kind',c.kind,'teamId',c.team_id,'jobId',c.job_id,
   'jobName',(select j.name from mir_core.jobs j where j.organization_id=org and j.id=c.job_id),
   'readOnly',coalesce((select j.archived from mir_core.jobs j where j.organization_id=org and j.id=c.job_id),false),
   'participants',(select coalesce(jsonb_agg(m.user_id),'[]') from mir_core.memberships m where m.organization_id=org and m.active and mir_core.chat_member_allowed(org,c.id,m.user_id)))
   from mir_core.conversations c where c.organization_id=org and c.id=conversation));
end$fn$;
create function public.mir_chat_conversations(org uuid,page_size integer default 20,page_before jsonb default null) returns jsonb
language plpgsql stable security definer set search_path=pg_catalog,mir_core as $fn$
declare size integer:=least(greatest(coalesce(page_size,20),1),50);items jsonb;last_item jsonb;more boolean;stamp timestamptz;cursor_id uuid;
begin
 if auth.uid() is null or not exists(select 1 from mir_core.memberships m where m.organization_id=org and m.user_id=auth.uid() and m.active and m.role in('admin','employee')) then raise exception 'Accès interne requis' using errcode='42501';end if;
 if page_before is not null then
  begin stamp:=(page_before->>'createdAt')::timestamptz;cursor_id:=(page_before->>'id')::uuid;exception when others then raise exception 'Curseur invalide' using errcode='22023';end;
  if not exists(select 1 from mir_core.conversations c where c.organization_id=org and c.id=cursor_id and c.created_at=stamp and mir_core.conversation_allowed(org,c.id)) then raise exception 'Curseur non autorisé' using errcode='22023';end if;
 end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',c.id,'kind',c.kind,'teamId',c.team_id,'jobId',c.job_id,'createdAt',c.created_at,
  'jobName',(select j.name from mir_core.jobs j where j.organization_id=org and j.id=c.job_id),
  'readOnly',coalesce((select j.archived from mir_core.jobs j where j.organization_id=org and j.id=c.job_id),false),
  'participants',(select coalesce(jsonb_agg(m.user_id order by m.user_id),'[]') from mir_core.memberships m where m.organization_id=org and m.active and mir_core.chat_member_allowed(org,c.id,m.user_id)),
  'lastMessage',(select mir_core.chat_message_json(org,m.id) from mir_core.messages m where m.organization_id=org and m.conversation_id=c.id order by m.sent_at desc,m.id desc limit 1),
  'lastActivity',coalesce((select m.sent_at from mir_core.messages m where m.organization_id=org and m.conversation_id=c.id order by m.sent_at desc,m.id desc limit 1),c.created_at),
  'unread',(select count(*) from mir_core.message_receipts r join mir_core.messages m on(m.organization_id,m.id)=(r.organization_id,r.message_id) where r.organization_id=org and r.user_id=auth.uid() and r.read_at is null and m.conversation_id=c.id)) order by c.created_at desc,c.id desc),'[]') into items from
  (select c.* from mir_core.conversations c where c.organization_id=org and mir_core.conversation_allowed(org,c.id) and(stamp is null or(c.created_at,c.id)<(stamp,cursor_id)) order by c.created_at desc,c.id desc limit size+1) c;
 more:=jsonb_array_length(items)>size;if more then items:=items-size;end if;last_item:=items->(jsonb_array_length(items)-1);
 return jsonb_build_object('items',items,'hasMore',more,'nextCursor',case when more then jsonb_build_object('createdAt',last_item->>'createdAt','id',last_item->>'id') end);
end$fn$;
create function public.mir_chat_search(org uuid,query_text text,page_size integer default 20,page_before jsonb default null) returns jsonb
language plpgsql stable security definer set search_path=pg_catalog,mir_core as $fn$
declare size integer:=least(greatest(coalesce(page_size,20),1),50);items jsonb;last_item jsonb;more boolean;stamp timestamptz;cursor_id uuid;
begin
 if auth.uid() is null or not exists(select 1 from mir_core.memberships m where m.organization_id=org and m.user_id=auth.uid() and m.active and m.role in('admin','employee')) then raise exception 'Accès interne requis' using errcode='42501';end if;
 if query_text is null or length(btrim(query_text)) not between 2 and 160 then raise exception 'Recherche invalide' using errcode='22023';end if;
 if page_before is not null then
  begin stamp:=(page_before->>'sentAt')::timestamptz;cursor_id:=(page_before->>'id')::uuid;exception when others then raise exception 'Curseur invalide' using errcode='22023';end;
  if not exists(select 1 from mir_core.messages m where m.organization_id=org and m.id=cursor_id and m.sent_at=stamp and mir_core.conversation_allowed(org,m.conversation_id)) then raise exception 'Curseur non autorisé' using errcode='22023';end if;
 end if;
 select coalesce(jsonb_agg(mir_core.chat_message_json(org,m.id) order by m.sent_at desc,m.id desc),'[]') into items from
  (select m.id,m.sent_at from mir_core.messages m where m.organization_id=org and mir_core.conversation_allowed(org,m.conversation_id)
   and strpos(lower(m.body),lower(btrim(query_text)))>0 and(stamp is null or(m.sent_at,m.id)<(stamp,cursor_id)) order by m.sent_at desc,m.id desc limit size+1) m;
 more:=jsonb_array_length(items)>size;if more then items:=items-size;end if;last_item:=items->(jsonb_array_length(items)-1);
 return jsonb_build_object('items',items,'hasMore',more,'nextCursor',case when more then jsonb_build_object('sentAt',last_item->>'sentAt','id',last_item->>'id') end);
end$fn$;
create function mir_core.chat_legacy_projection(org uuid) returns jsonb
language plpgsql stable set search_path=pg_catalog,mir_core as $fn$
declare listing jsonb:=public.mir_chat_conversations(org,20,null);conversation jsonb;page jsonb;messages jsonb:='[]';pages jsonb:='{}';
begin
 for conversation in select value from jsonb_array_elements(listing->'items') loop
  page:=public.mir_chat_messages(org,(conversation->>'id')::uuid,20,null);
  pages:=pages||jsonb_build_object(conversation->>'id',page-'items');
  select coalesce(jsonb_agg(value order by (value->>'sentAt')::timestamptz,value->>'id'),'[]') into page from jsonb_array_elements(page->'items');
  messages:=messages||page;
 end loop;
 return jsonb_build_object('conversations',listing->'items','conversationPage',listing-'items','messages',messages,'messagePages',pages);
end$fn$;
create or replace function public.mir_messaging_snapshot(org uuid) returns jsonb
language plpgsql stable security definer set search_path=pg_catalog,mir_core as $fn$
begin
 if auth.uid() is null or not exists(select 1 from mir_core.memberships m where m.organization_id=org and m.user_id=auth.uid() and m.active and m.role in('admin','employee')) then raise exception 'Accès interne requis' using errcode='42501';end if;
 return mir_core.chat_legacy_projection(org)||jsonb_build_object(
 'contacts',coalesce((select jsonb_agg(jsonb_build_object('id',p.user_id,'name',coalesce(nullif(p.display_name,''),p.user_id::text),'role',p.staff_role) order by p.display_name,p.user_id) from mir_core.staff_capabilities p join mir_core.memberships m on(m.organization_id,m.user_id)=(p.organization_id,p.user_id) where p.organization_id=org and p.active and m.active and p.user_id<>auth.uid()),'[]'),
 'teams',coalesce((select jsonb_agg(jsonb_build_object('id',t.id,'name',t.name,'leaderId',t.leader_id)) from mir_core.teams t join mir_core.team_members tm on(tm.organization_id,tm.team_id)=(t.organization_id,t.id) where t.organization_id=org and t.active and tm.active and tm.user_id=auth.uid()),'[]'));
end$fn$;
-- Additional restrictive policies: original permissive policies remain byte-for-byte intact.
create function mir_core.chat_attachment_writable(path text) returns boolean
language plpgsql stable security definer set search_path=pg_catalog,mir_core as $fn$
declare org uuid;conversation uuid;
begin
 if auth.uid() is null or not mir_core.internal_object_allowed(path,true) then return false;end if;
 org:=split_part(path,'/',1)::uuid;conversation:=split_part(path,'/',3)::uuid;
 return exists(select 1 from mir_core.conversations c left join mir_core.jobs j on(j.organization_id,j.id)=(c.organization_id,c.job_id)
  where c.organization_id=org and c.id=conversation and (c.kind<>'job' or not j.archived));
exception when invalid_text_representation then return false;
end$fn$;
create policy mir_chat_phase3a_insert on storage.objects as restrictive for insert to authenticated with check(
 case when bucket_id='mir-internal' and split_part(name,'/',2)='message' then
  mir_core.chat_attachment_writable(name) and mir_core.chat_storage_object(name,owner,owner_id,metadata)
 else true end);
create policy mir_chat_phase3a_update on storage.objects as restrictive for update to authenticated
 using(not(bucket_id='mir-internal' and split_part(name,'/',2)='message'))
 with check(not(bucket_id='mir-internal' and split_part(name,'/',2)='message'));
create policy mir_chat_phase3a_select on storage.objects as restrictive for select to authenticated using(
 case when bucket_id='mir-internal' and split_part(name,'/',2)='message' then
 mir_core.internal_object_allowed(name,false) and mir_core.chat_storage_object(name,owner,owner_id,metadata)
 else true end);
$install$;
 -- Restrictive DELETE uses a narrow predicate, not a direct private-table query.
 execute $install$
create function mir_core.chat_attachment_unlinked(path text) returns boolean
language sql stable security definer set search_path=pg_catalog,mir_core as $fn$
 select auth.uid() is not null and mir_core.internal_object_allowed(path,true) and not exists(select 1 from mir_core.messages m where m.attachment_path=path);
$fn$;
create policy mir_chat_phase3a_delete on storage.objects as restrictive for delete to authenticated using(case when bucket_id='mir-internal' and split_part(name,'/',2)='message' then mir_core.chat_attachment_unlinked(name) else true end);
$install$;
 -- Preserve private conversation semantics; only make its INSERT resilient to the additive column.
 select pg_get_functiondef('public.mir_conversation_private(uuid,uuid)'::regprocedure) into source;
 rewritten:=replace(source,'insert into mir_core.conversations values(org,result,',
  'insert into mir_core.conversations(organization_id,id,kind,team_id,created_by,created_at) values(org,result,');
 if rewritten=source then raise exception 'INSERT privé incompatible' using errcode='55000';end if;execute rewritten;
 -- Remove the second unbounded legacy history without changing any non-chat section or role label.
 select pg_get_functiondef('public.mir_employee_operations_snapshot(uuid,uuid)'::regprocedure) into source;
 rewritten:=regexp_replace(source,'''conversations'',coalesce\(.*?''hrRequests'',',
  '''conversations'',(mir_core.chat_legacy_projection(org)->''conversations''), ''messages'',(mir_core.chat_legacy_projection(org)->''messages''), ''hrRequests'',','s');
 if rewritten=source then raise exception 'Projection historique incompatible' using errcode='55000';end if;
 rewritten:=replace(rewritten,'n.organization_id=org and n.user_id=auth.uid()',
  'n.organization_id=org and n.user_id=auth.uid() and (n.kind<>''message'' or exists(select 1 from mir_core.messages msg where msg.organization_id=org and msg.id=n.entity_id and mir_core.conversation_allowed(org,msg.conversation_id)))');
 execute rewritten;
 -- Existing function ACLs are preserved by CREATE OR REPLACE, including service_role if present.
 -- New APIs get explicit minimal EXECUTE. No table privilege is added.
 foreach signature in array array['public.mir_conversation_job(uuid,uuid)','public.mir_chat_messages(uuid,uuid,integer,jsonb)',
  'public.mir_chat_conversations(uuid,integer,jsonb)','public.mir_chat_search(uuid,text,integer,jsonb)',
  'public.mir_message_attachment_validate(uuid,uuid,text)','mir_core.chat_storage_object(text,uuid,text,jsonb)','mir_core.chat_attachment_unlinked(text)','mir_core.chat_attachment_writable(text)'] loop
  execute 'revoke all on function '||signature||' from public,anon';execute 'grant execute on function '||signature||' to authenticated';
  if exists(select 1 from pg_roles where rolname='service_role') then execute 'grant execute on function '||signature||' to service_role';end if;
 end loop;
 foreach signature in array array['mir_core.chat_member_allowed(uuid,uuid,uuid)','mir_core.chat_message_json(uuid,uuid)','mir_core.chat_legacy_projection(uuid)'] loop
  execute 'revoke all on function '||signature||' from public,anon,authenticated';
 end loop;
 execute $install$
create function mir_core.chat_phase3a_catalog() returns text language sql stable set search_path=pg_catalog as $fn$
 select md5(concat(
 (select string_agg(p.oid::regprocedure::text||p.prosrc||coalesce(p.proacl::text,'')||p.prosecdef::text||coalesce(p.proconfig::text,''),'|' order by p.oid)
  from pg_proc p join pg_namespace n on n.oid=p.pronamespace where (n.nspname='mir_core' and(p.proname like 'chat_%' or p.proname='conversation_allowed'))
   or(n.nspname='public' and p.proname in('mir_chat_messages','mir_chat_conversations','mir_chat_search','mir_message_attachment_validate','mir_conversation_job','mir_conversation_private','mir_conversation_team','mir_conversation_open','mir_message_send','mir_message_ack','mir_messaging_snapshot','mir_employee_operations_snapshot'))),
 (select string_agg(pg_get_constraintdef(oid),'|' order by conname) from pg_constraint where conrelid='mir_core.conversations'::regclass),
 (select string_agg(indexdef,'|' order by indexname) from pg_indexes where schemaname='mir_core' and tablename in('conversations','messages','message_receipts')),
 (select string_agg(to_jsonb(p)::text,'|' order by policyname) from pg_policies p where schemaname='storage' and(policyname like 'mir_chat_phase3a_%' or policyname like 'mir_internal_%')),
 (select string_agg(relname||relrowsecurity::text||coalesce(relacl::text,''),'|' order by relname) from pg_class where oid in('mir_core.conversations'::regclass,'mir_core.messages'::regclass,'mir_core.message_receipts'::regclass,'mir_core.conversation_participants'::regclass)),
 (select (public,file_size_limit,allowed_mime_types)::text from storage.buckets where id='mir-internal')));
$fn$;
revoke all on function mir_core.chat_phase3a_catalog() from public,anon,authenticated;
$install$;
 execute 'select mir_core.chat_phase3a_catalog()' into source;
 execute format('comment on column mir_core.conversations.job_id is %L','MIR chat Phase3A v1:'||source);
end$migration$;
commit;
